/** Shared content types. Edit the data files, not the components. */

export interface Link {
  label: string;
  href: string;
}

export interface ProjectImage {
  /** Key in src/data/images.json (generated by `npm run images`). */
  name: string;
  alt: string;
}

export interface Project {
  slug: string;
  number: string;
  title: string;
  /** Shorter name for tight spots (spotlight progress labels), e.g. "RER". */
  shortTitle?: string;
  /** Short line under the case-study title. */
  tagline: string;
  /** True while the tagline is a placeholder you still need to confirm. */
  taglineTodo?: boolean;
  /** "Web app", "Mobile app", "Embedded"... shown in the work index and as a sticker. */
  type: string;
  /** Tech shown in the work index row. */
  tech: string[];
  /** Overview statement; wrap the highlighted words in [[double brackets]]. */
  statement: string;
  /** Original description from the old site, kept verbatim. */
  description: string;
  /** One sentence shown in the home spotlight (first sentence of the description). */
  summary: string;
  /** Spotlight block colour. Text pairs are fixed to AA-safe combinations. */
  tone: SpotlightTone;
  /** Extra overview paragraphs; empty strings render as visible TODO notes. */
  overview: string[];
  role: string | null;
  year: string | null;
  /** Live product URL. The spotlight button becomes "Visit site ↗" (new tab). */
  liveUrl?: string;
  links: Link[];
  image: ProjectImage | null;
  /** Optional phone screenshot; the spotlight only shows its phone frame when this exists. */
  mobileImage?: ProjectImage | null;
  /** Screenshots 2 and 3; the gallery stays hidden until both exist. */
  gallery: ProjectImage[];
}

export type SpotlightTone = 'grape' | 'plum' | 'bubblegum' | 'apricot';

export type SkillLogo =
  | { kind: 'icon'; slug: string }
  | { kind: 'mono'; text: string };

export interface Skill {
  name: string;
  logo: SkillLogo;
  /** Added in the redesign brief; confirm or delete. */
  todo?: boolean;
}

export interface SkillGroup {
  id: string;
  title: string;
  skills: Skill[];
  /** Optional line under the title (used by AI & automation). */
  subline?: string;
  variant?: 'default' | 'specialty' | 'row';
}

export interface Certificate {
  title: string;
  issuer: string;
  url: string;
}

export interface ExperienceItem {
  role: string;
  org: string | null;
  start: string;
  /** null means "Present". */
  end: string | null;
  bullets: string[];
}

export interface EducationItem {
  school: string;
  degree: string;
  date: string;
  bullets: string[];
}
